using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;
using System.Runtime.Intrinsics.X86;
using System.Runtime.Intrinsics.Arm;

namespace ByteBitReverse;

public class BitReverser
{
    // Lookup table for nibble bit-reversal (0x0→0x0, 0x1→0x8, ..., 0xF→0xF)
    private static ReadOnlySpan<byte> NibbleLut =>
    [
        0x00, 0x08, 0x04, 0x0C, 0x02, 0x0A, 0x06, 0x0E,
        0x01, 0x09, 0x05, 0x0D, 0x03, 0x0B, 0x07, 0x0F
    ];

    public static void ReverseInPlace(Span<byte> data)
    {
        if (Avx2.IsSupported)
        {
            ReverseAvx2(data);
        }
        else if (Ssse3.IsSupported)
        {
            ReverseSsse3(data);
        }
        else if (AdvSimd.Arm64.IsSupported)
        {
            ReverseNeon(data);
        }
        else
        {
            ReverseScalar(data);
        }
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static void ReverseAvx2(Span<byte> data)
    {
        var lut = Vector256.Create(NibbleLut[0], NibbleLut[1], NibbleLut[2], NibbleLut[3],
            NibbleLut[4], NibbleLut[5], NibbleLut[6], NibbleLut[7],
            NibbleLut[8], NibbleLut[9], NibbleLut[10], NibbleLut[11],
            NibbleLut[12], NibbleLut[13], NibbleLut[14], NibbleLut[15],
            NibbleLut[0], NibbleLut[1], NibbleLut[2], NibbleLut[3],
            NibbleLut[4], NibbleLut[5], NibbleLut[6], NibbleLut[7],
            NibbleLut[8], NibbleLut[9], NibbleLut[10], NibbleLut[11],
            NibbleLut[12], NibbleLut[13], NibbleLut[14], NibbleLut[15]);
        var mask = Vector256.Create((byte)0x0F);

        ref byte ptr = ref MemoryMarshal.GetReference(data);
        int i = 0;
        int len = data.Length;

        for (; i + 32 <= len; i += 32)
        {
            var vec = Vector256.LoadUnsafe(ref ptr, (nuint)i);
            var lo = Avx2.And(vec, mask);
            var hi = Avx2.And(Avx2.ShiftRightLogical(vec.AsInt16(), 4).AsByte(), mask);
            var reversedLo = Avx2.Shuffle(lut, lo);
            var reversedHi = Avx2.Shuffle(lut, hi);
            var result = Avx2.Or(Avx2.ShiftLeftLogical(reversedLo.AsInt16(), 4).AsByte(), reversedHi);
            result.StoreUnsafe(ref ptr, (nuint)i);
        }

        // Handle remaining bytes with scalar LUT
        for (; i < len; i++)
        {
            byte b = Unsafe.Add(ref ptr, i);
            Unsafe.Add(ref ptr, i) = (byte)((NibbleLut[b & 0x0F] << 4) | NibbleLut[b >> 4]);
        }
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static void ReverseSsse3(Span<byte> data)
    {
        var lut = Vector128.Create(NibbleLut[0], NibbleLut[1], NibbleLut[2], NibbleLut[3],
            NibbleLut[4], NibbleLut[5], NibbleLut[6], NibbleLut[7],
            NibbleLut[8], NibbleLut[9], NibbleLut[10], NibbleLut[11],
            NibbleLut[12], NibbleLut[13], NibbleLut[14], NibbleLut[15]);
        var mask = Vector128.Create((byte)0x0F);

        ref byte ptr = ref MemoryMarshal.GetReference(data);
        int i = 0;
        int len = data.Length;

        for (; i + 16 <= len; i += 16)
        {
            var vec = Vector128.LoadUnsafe(ref ptr, (nuint)i);
            var lo = Sse2.And(vec, mask);
            var hi = Sse2.And(Sse2.ShiftRightLogical(vec.AsInt16(), 4).AsByte(), mask);
            var reversedLo = Ssse3.Shuffle(lut, lo);
            var reversedHi = Ssse3.Shuffle(lut, hi);
            var result = Sse2.Or(Sse2.ShiftLeftLogical(reversedLo.AsInt16(), 4).AsByte(), reversedHi);
            result.StoreUnsafe(ref ptr, (nuint)i);
        }

        for (; i < len; i++)
        {
            byte b = Unsafe.Add(ref ptr, i);
            Unsafe.Add(ref ptr, i) = (byte)((NibbleLut[b & 0x0F] << 4) | NibbleLut[b >> 4]);
        }
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static void ReverseNeon(Span<byte> data)
    {
        // ARM NEON: use RBIT (reverse bits) via AdvSimd
        ref byte ptr = ref MemoryMarshal.GetReference(data);
        int i = 0;
        int len = data.Length;

        // NEON lookup table approach (same as SSSE3 but with ARM intrinsics)
        var lut = Vector128.Create(NibbleLut[0], NibbleLut[1], NibbleLut[2], NibbleLut[3],
            NibbleLut[4], NibbleLut[5], NibbleLut[6], NibbleLut[7],
            NibbleLut[8], NibbleLut[9], NibbleLut[10], NibbleLut[11],
            NibbleLut[12], NibbleLut[13], NibbleLut[14], NibbleLut[15]);
        var mask = Vector128.Create((byte)0x0F);

        for (; i + 16 <= len; i += 16)
        {
            var vec = Vector128.LoadUnsafe(ref ptr, (nuint)i);
            var lo = AdvSimd.And(vec, mask);
            var hi = AdvSimd.And(AdvSimd.ShiftRightLogical(vec, 4), mask);
            var reversedLo = AdvSimd.Arm64.VectorTableLookup(lut, lo);
            var reversedHi = AdvSimd.Arm64.VectorTableLookup(lut, hi);
            var result = AdvSimd.Or(AdvSimd.ShiftLeftLogical(reversedLo, 4), reversedHi);
            result.StoreUnsafe(ref ptr, (nuint)i);
        }

        for (; i < len; i++)
        {
            byte b = Unsafe.Add(ref ptr, i);
            Unsafe.Add(ref ptr, i) = (byte)((NibbleLut[b & 0x0F] << 4) | NibbleLut[b >> 4]);
        }
    }

    private static void ReverseScalar(Span<byte> data)
    {
        ref byte ptr = ref MemoryMarshal.GetReference(data);
        int len = data.Length;

        for (int i = 0; i < len; i++)
        {
            byte b = Unsafe.Add(ref ptr, i);
            Unsafe.Add(ref ptr, i) = (byte)((NibbleLut[b & 0x0F] << 4) | NibbleLut[b >> 4]);
        }
    }
}

